class Solution:
    def minInversionCount(self, nums: List[int], k: int) -> int:
        n = len(nums); best = float('inf')
        for l in range(n - k + 1):
            c = 0
            for i in range(l, l + k):
                for j in range(i + 1, l + k):
                    if nums[i] > nums[j]: c += 1
            best = min(best, c)
        return best

