        int n = nums.size(), best = INT_MAX;
        for (int l = 0; l + k <= n; l++) {
            int c = 0;
            for (int i = l; i < l + k; i++)
                for (int j = i + 1; j < l + k; j++)
                    if (nums[i] > nums[j]) c++;
            best = min(best, c);
        }
        return best;
    }
};

