class Solution:
    def minInversionCount(self, nums: List[int], k: int) -> int:
        import bisect
        sv = sorted(set(nums)); m = len(sv)
        bit = [0] * (m + 1)
        def upd(i, d):
            i += 1
            while i <= m: bit[i] += d; i += i & -i
        def pre(i):
            i += 1; s = 0
            while i > 0: s += bit[i]; i -= i & -i
            return s
        cur = 0; best = float('inf')
        for r, x in enumerate(nums):
            xi = bisect.bisect_left(sv, x)
            cur += pre(m - 1) - pre(xi)
            upd(xi, 1)
            if r - k >= 0:
                yi = bisect.bisect_left(sv, nums[r - k])
                cur -= pre(yi - 1)
                upd(yi, -1)
            if r >= k - 1: best = min(best, cur)
        return best

