class Solution {
public:
    int minInversionCount(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> sv = nums;
        sort(sv.begin(), sv.end()); sv.erase(unique(sv.begin(), sv.end()), sv.end());
        int m = sv.size();
        vector<int> bit(m + 1, 0);
        auto upd = [&](int i, int d) { for (i++; i <= m; i += i & -i) bit[i] += d; };
        auto pre = [&](int i) { int s = 0; for (i++; i > 0; i -= i & -i) s += bit[i]; return s; };
        long long cur = 0, best = LLONG_MAX;
        for (int r = 0; r < n; r++) {
            int xi = lower_bound(sv.begin(), sv.end(), nums[r]) - sv.begin();
            cur += pre(m - 1) - pre(xi);
            upd(xi, 1);
            if (r - k >= 0) {
                int yi = lower_bound(sv.begin(), sv.end(), nums[r - k]) - sv.begin();
                cur -= pre(yi - 1);
                upd(yi, -1);
            }
            if (r >= k - 1) best = min(best, cur);
        }
        return (int)best;
    }
};

