class Solution {
    public int minInversionCount(int[] nums, int k) {
        int n = nums.length;
        int[] sv = nums.clone();
        Arrays.sort(sv);
        int m = 0;
        for (int i = 0; i < n; i++) if (i == 0 || sv[i] != sv[i-1]) sv[m++] = sv[i];
        int[] bit = new int[m + 1];
        java.util.function.BiConsumer<Integer,Integer> upd = (ii, d) -> {
            for (int i = ii + 1; i <= m; i += i & -i) bit[i] += d;
        };
        java.util.function.IntUnaryOperator pre = ii -> {
            int s = 0; for (int i = ii + 1; i > 0; i -= i & -i) s += bit[i]; return s;
        };
        long cur = 0, best = Long.MAX_VALUE;
        for (int r = 0; r < n; r++) {
            int xi = Arrays.binarySearch(sv, 0, m, nums[r]);
            cur += pre.applyAsInt(m - 1) - pre.applyAsInt(xi);
            upd.accept(xi, 1);
            if (r - k >= 0) {
                int yi = Arrays.binarySearch(sv, 0, m, nums[r - k]);
                cur -= yi > 0 ? pre.applyAsInt(yi - 1) : 0;
                upd.accept(yi, -1);
            }
            if (r >= k - 1) best = Math.min(best, cur);
        }
        return (int) best;
    }
}

