var minInversionCount = function(nums, k) {
    const n = nums.length;
    const sv = [...new Set(nums)].sort((a, b) => a - b);
    const m = sv.length, bit = new Array(m + 1).fill(0);
    const upd = (i, d) => { for (i++; i <= m; i += i & -i) bit[i] += d; };
    const pre = i => { i++; let s = 0; while (i > 0) { s += bit[i]; i -= i & -i; } return s; };
    let cur = 0, best = Infinity;
    for (let r = 0; r < n; r++) {
        const xi = sv.indexOf(nums[r]);
        cur += pre(m - 1) - pre(xi);
        upd(xi, 1);
        if (r - k >= 0) {
            const yi = sv.indexOf(nums[r - k]);
            cur -= yi > 0 ? pre(yi - 1) : 0;
            upd(yi, -1);
        }
        if (r >= k - 1) best = Math.min(best, cur);
    }
    return best;
};
